// Превращает строки листа Settings (key/value) в объект и прокидывает дальше.
const rows = $input.all().map(i => i.json);
const settings = {};
for (const r of rows) {
  const key = (r.key ?? r.Key ?? '').toString().trim();
  if (!key) continue;
  settings[key] = (r.value ?? r.Value ?? '').toString().trim();
}
function bool(v, def) {
  if (v === undefined || v === '') return def;
  return String(v).toLowerCase() === 'true' || v === '1';
}
function num(v, def) {
  const n = Number(v);
  return Number.isFinite(n) ? n : def;
}
const cfg = {
  owner_chat_id: settings.owner_chat_id || '<REDACTED_CHAT_ID>',
  manager_chat_id: settings.manager_chat_id || '',
  allowed_chat_ids: (settings.allowed_chat_ids || settings.owner_chat_id || '<REDACTED_CHAT_ID>'),
  sla_hot_hours: num(settings.sla_hot_hours, 4),
  sla_warm_hours: num(settings.sla_warm_hours, 24),
  sla_repeat_hours: num(settings.sla_repeat_hours, 6),
  default_responsible: settings.default_responsible || 'Геннадий',
  ai_model: settings.ai_model || 'gpt-4.1-mini',
  ai_enabled_for_hot: bool(settings.ai_enabled_for_hot, true),
  ai_enabled_for_warm: bool(settings.ai_enabled_for_warm, true),
  ai_enabled_for_cold: bool(settings.ai_enabled_for_cold, false),
  auto_reply_enabled: bool(settings.auto_reply_enabled, false),
  auto_reply_default_lang: (settings.auto_reply_default_lang || 'ru').toLowerCase(),
  follow_up_enabled: bool(settings.follow_up_enabled, false),
  followup_hot_hours: num(settings.followup_hot_hours, 24),
  followup_warm_hours: num(settings.followup_warm_hours, 72),
  timezone: settings.timezone || 'Europe/Chisinau',
  currency: settings.currency || 'EUR'
};
return [{ json: { settings: cfg } }];

// Build Followup Plan — эмитит item_type: new_followup (создать) и due_alert (напомнить).
const cfg = (function(){ try { return $('Settings to Object').first().json.settings || {}; } catch(e){ return {}; } })();
const now = new Date();
const enabled = String(cfg.follow_up_enabled).toLowerCase() === 'true';
const hotH = Number(cfg.followup_hot_hours || 24) || 24;
const warmH = Number(cfg.followup_warm_hours || 72) || 72;

const pipe = $('Get Pipeline Rows').all().map(i => i.json)
  .filter(r => r && Object.keys(r).length > 0 && (r.lead_id || r.company || r.name));
let followups = [];
try { followups = $('Get Followups').all().map(i => i.json).filter(r => r && r.followup_id); } catch(e){ followups = []; }

function val(r, ...keys){ for(const k of keys){ if(r[k]!==undefined&&r[k]!==null&&String(r[k]).trim()!=='') return String(r[k]).trim(); } return ''; }
function norm(v){ return String(v ?? '').trim().toLowerCase(); }
function isClosed(stage){ const s=norm(stage); return ['won','lost','closed','nurture','incomplete','закрыт'].some(x=>s.includes(x)); }
function isSnoozedFuture(r){ if(norm(val(r,'sla_status'))!=='snoozed') return false; const u=new Date(val(r,'sla_snooze_until')); return !Number.isNaN(u.getTime())&&u>now; }
function addHours(iso, h){ const d=new Date(iso||Date.now()); if(Number.isNaN(d.getTime())) return ''; d.setHours(d.getHours()+h); return d.toISOString(); }
function slug(t){ return String(t).replace(/[^a-z0-9]+/gi,'-').replace(/(^-|-$)/g,'').toLowerCase(); }
function stamp(){ const d=new Date(); const p=n=>String(n).padStart(2,'0'); return ''+d.getUTCFullYear()+p(d.getUTCMonth()+1)+p(d.getUTCDate())+p(d.getUTCHours())+p(d.getUTCMinutes()); }
function dkey(v){ if(!v) return ''; const d=new Date(v); return Number.isNaN(d.getTime())?String(v):d.toISOString().slice(0,16).replace('T',' '); }

const out = [];

// ---------- A) NEW planned followups (только если follow_up_enabled) ----------
if (enabled) {
  for (const r of pipe) {
    const stage = val(r,'deal_stage');
    if (isClosed(stage)) continue;
    const priority = val(r,'priority').toUpperCase();
    if (priority === 'COLD' || priority === 'INCOMPLETE') continue;
    const sla = norm(val(r,'sla_status'));
    if (sla === 'done' || sla === 'nurture') continue;

    let type = '', dueAt = '';
    const nfu = val(r,'next_follow_up_at');
    if (norm(stage).includes('documents requested')) {
      type = 'Document reminder';
      const drq = val(r,'documents_requested_at');
      dueAt = drq ? addHours(drq, 48) : nfu;
    } else if (norm(stage).includes('proposal sent')) {
      type = 'Proposal follow-up';
      const psa = val(r,'proposal_sent_at');
      dueAt = psa ? addHours(psa, 72) : nfu;
    } else if (priority === 'HOT') {
      type = 'HOT follow-up';
      dueAt = nfu || addHours(val(r,'created_at'), hotH);
    } else if (priority === 'WARM') {
      type = 'WARM follow-up';
      dueAt = nfu || addHours(val(r,'created_at'), warmH);
    } else continue;
    if (!dueAt) continue;

    const leadId = val(r,'lead_id');
    const forLead = followups.filter(f => norm(f.lead_id) === norm(leadId));
    const hasFuture = forLead.some(f => ['planned','sent'].includes(norm(f.status)) && new Date(f.due_at) > now);
    const hasSameType = forLead.some(f => norm(f.type) === norm(type));
    if (hasFuture || hasSameType) continue;

    const company = val(r,'company')||'-';
    const name = val(r,'name')||'-';
    const contact = [val(r,'phone'),val(r,'telegram'),val(r,'email')].filter(Boolean).join(' ')||'no contact';
    const zone = val(r,'financial_zone')||'-';
    const nextAction = val(r,'next_action')||'contact lead';
    const message_template =
`Follow-up needed
Lead ID: ${leadId}
Company: ${company}
Contact: ${name} ${contact}
Priority/Zone: ${priority}/${zone}
Stage: ${stage||'New'}
Next action: ${nextAction}
Reason: ${val(r,'priority_reason')||'-'}`;

    out.push({ json: {
      item_type: 'new_followup',
      followup_id: `FU-${leadId}-${slug(type)}-${stamp()}`,
      created_at: now.toISOString(),
      lead_id: leadId,
      due_at: dueAt,
      type,
      status: 'Planned',
      priority,
      channel: 'Telegram',
      message_template,
      done_at: '',
      result: '',
      note: ''
    }});
  }
}

