const pipeById = {};
for (const r of pipe) { const id = norm(val(r,'lead_id')); if (id) pipeById[id] = r; }

for (const f of followups) {
  if (norm(f.status) !== 'planned') continue;
  const due = new Date(val(f,'due_at'));
  if (Number.isNaN(due.getTime()) || due > now) continue;   // due_at <= now
  const leadId = val(f,'lead_id');
  const r = pipeById[norm(leadId)];
  if (r) {
    if (isClosed(val(r,'deal_stage'))) continue;
    const sla = norm(val(r,'sla_status'));
    if (sla === 'done' || sla === 'nurture') continue;
    if (isSnoozedFuture(r)) continue;
  }
  const company = r ? (val(r,'company')||'-') : '-';
  const name = r ? (val(r,'name')||'-') : '-';
  const priority = r ? (val(r,'priority')||val(f,'priority')||'-') : (val(f,'priority')||'-');
  const zone = r ? (val(r,'financial_zone')||'-') : '-';
  const stage = r ? (val(r,'deal_stage')||'New') : '-';
  const nextAction = r ? (val(r,'next_action')||'-') : '-';
  const type = val(f,'type')||'follow-up';

  const telegram_message =
`FINMENTOR Follow-up Reminder
${company} / ${name}
Lead ID: ${leadId}
Priority/Zone: ${priority}/${zone}
Type: ${type}
Due: ${dkey(val(f,'due_at'))}
Stage: ${stage}
Next action: ${nextAction}`;

  out.push({ json: {
    item_type: 'due_alert',
    followup_id: val(f,'followup_id'),
    lead_id: leadId,
    type,
    priority,
    financial_zone: zone,
    due_at: val(f,'due_at'),
    telegram_message
  }});
}

return out;

// Activity на каждый созданный planned followup.
const items = $('Build Followup Plan').all().map(i => i.json).filter(x => x.item_type === 'new_followup');
return items.map(f => ({ json: {
  activity_id: `FU-ACT-${f.lead_id}-${Date.now()}-${Math.floor(Math.random()*1000)}`,
  ts: new Date().toISOString(),
  lead_id: f.lead_id,
  actor: 'system:followup',
  channel: 'automation',
  action: 'followup_planned',
  detail: `Followup planned: type=${f.type}; due_at=${f.due_at}; priority=${f.priority}`
}}));

