// Читаем due_alert items из плана (Telegram отдаёт свой API-ответ).
const due = $('Build Followup Plan').all().map(i => i.json).filter(x => x.item_type === 'due_alert');
const now = new Date().toISOString();
return due.map(d => ({ json: {
  followup_id: d.followup_id,
  status: 'Sent',
  result: 'Telegram reminder sent',
  note: `owner reminder ${now}`
}}));

