const due = $('Build Followup Plan').all().map(i => i.json).filter(x => x.item_type === 'due_alert');
const hot = due.filter(d => String(d.priority).toUpperCase() === 'HOT').length;
const warm = due.filter(d => String(d.priority).toUpperCase() === 'WARM').length;
return [{ json: {
  activity_id: `FU-REM-${Date.now()}`,
  ts: new Date().toISOString(),
  lead_id: 'FOLLOWUP',
  actor: 'system:followup',
  channel: 'telegram',
  action: 'followup_reminder_sent',
  detail: `Followup reminder sent: due_count=${due.length}; hot=${hot}; warm=${warm}`
